const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const sharp = require('sharp');

async function main() {
  const root = path.resolve(__dirname, '../..');
  const directory = path.join(root, 'marketing/gameplay-gallery-2026-09-17');
  const scenes = [
    ['01-live-match.png', 'Call the match', 'Live radar, both lineups and round decisions. Collapsed navigation gives the match more room.'],
    ['02-player-development.png', 'Find your next star', 'A focused player profile with portrait, strengths, potential and contract information.'],
    ['03-match-analysis.png', 'Learn from every round', 'Actual match statistics, MVP and round history, framed around the analysis instead of the large score header.'],
    ['04-scouting.png', 'Build your shortlist', 'Recruitment with a selected player dossier, rather than an empty selection panel.'],
    ['05-build-your-club.png', 'Build the club behind the team', 'Facility artwork and upgrade decisions add visual variety to the management gallery.'],
    ['06-equipment.png', 'Equip your squad', 'Hardware progression with visible costs and effects.'],
    ['07-contracts-and-budget.png', 'Make the numbers work', 'Payroll and contract commitments connect the finances to individual players.'],
    ['08-club-overview.png', 'Plan your next move', 'The club dashboard connects the next match with weekly management choices.'],
  ];
  const screenshots = [];
  for (const [file, title, purpose] of scenes) {
    const bytes = fs.readFileSync(path.join(directory, file));
    const meta = await sharp(bytes).metadata();
    if (meta.width !== 1920 || meta.height !== 1080 || meta.format !== 'png') throw new Error(`Invalid capture: ${file} ${meta.width}x${meta.height}`);
    screenshots.push({file,title,purpose,width:meta.width,height:meta.height,sha256:crypto.createHash('sha256').update(bytes).digest('hex')});
  }
  const manifest = {capturedOn:'2026-09-17',buildId:fs.readFileSync(path.join(root,'.next/BUILD_ID'),'utf8').trim(),capture:'Unedited CUA browser viewport captures, 1920x1080, local production server localhost:3358. New isolated Alex Morgan career; not Steam client installation screenshots.',steamUploaded:false,overlays:false,retouched:false,screenshots};
  fs.writeFileSync(path.join(directory,'manifest.json'),JSON.stringify(manifest,null,2)+'\n');
  fs.writeFileSync(path.join(directory,'index.html'),`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Esports Manager — gallery selection</title><style>*{box-sizing:border-box}body{margin:0;background:#090e16;color:#f3f6fa;font:16px/1.55 system-ui}main{max-width:1440px;margin:auto;padding:48px 32px}header{max-width:850px;margin-bottom:36px}.eyebrow{color:#70dbc8;letter-spacing:.16em;font-size:12px;font-weight:700}h1{font-size:clamp(32px,5vw,64px);line-height:1.05;letter-spacing:-.04em;margin:16px 0}p{color:#a7b5c7}nav{display:flex;gap:10px;flex-wrap:wrap;margin:24px 0}nav a{border:1px solid #2b3d51;border-radius:30px;padding:8px 15px;text-decoration:none}a{color:#9cebdc}.grid{display:grid;grid-template-columns:1fr 1fr;gap:28px}article{background:#111b28;border:1px solid #273548;border-radius:14px;overflow:hidden}article:first-child{grid-column:1/-1}img{width:100%;display:block;aspect-ratio:16/9}section{padding:20px 24px}h2{margin:0;font-size:23px}section p{margin:8px 0 0;font-size:14px}.number{color:#70dbc8;font-size:12px;letter-spacing:.1em;margin-bottom:8px}.note{border-top:1px solid #273548;margin-top:40px;padding-top:24px;font-size:14px}@media(max-width:760px){.grid{grid-template-columns:1fr}main{padding:24px 16px}}</style></head><body><main><header><div class="eyebrow">ESPORTS MANAGER: FPS / STORE GALLERY</div><h1>Your club.<br>Your next big decision.</h1><p>A more varied eight-image selection: match action first, then players, analysis and the business behind the team.</p><nav><a href="../gameplay-gallery-2026-09-16/index.html">Previous gallery</a><a href="manifest.json">Capture manifest</a></nav><p>1920 × 1080 PNG · Current local production build · Not uploaded to Steam</p></header><div class="grid">${screenshots.map((s,i)=>`<article><a href="${s.file}"><img src="${s.file}" alt="${s.title}" ${i?'loading="lazy"':''}></a><section><div class="number">${String(i+1).padStart(2,'0')} / GAMEPLAY</div><h2>${s.title}</h2><p>${s.purpose}</p></section></article>`).join('')}</div><p class="note">These headings belong to this preview page only. The PNGs contain actual game UI with no added marketing text or generated gameplay. Scene selection is editorial judgment, not a measured conversion improvement.</p></main></body></html>`);
  fs.writeFileSync(path.join(directory,'README.md'),`# Refreshed gameplay gallery — 17 September 2026\n\nEight unedited 1920x1080 PNG captures. Open index.html to preview; upload only the eight numbered PNG files to Steam Screenshot Assets in filename order. Do not upload the HTML or manifest. No files from the previous gallery were modified.\n\n## What changed\n\n- Live match leads the sequence instead of a dashboard.\n- Match navigation collapsed to increase space for gameplay.\n- Results framed on MVP, round history and statistics.\n- Scouting includes a selected player dossier.\n- Facilities and equipment replace repetitive training/squad views.\n- Payroll shows player commitments alongside the budget.\n\n## Inspiration\n\nReviewed the current Steam Early Access top-seller listing and the Slay the Spire 2 and Schedule I store pages. Applied the general approach of showing the playable activity, readable decisions and varied systems. No competitor artwork was copied, and sales performance is not guaranteed.\n\n- https://store.steampowered.com/search/?filter=topsellers&genre=Early+Access\n- https://store.steampowered.com/app/2868840/Slay_the_Spire_2/\n- https://store.steampowered.com/app/3164500/Schedule_I/\n\n## Capture status\n\nBuild: ${manifest.buildId}. New local career at localhost:3358. Not native Steam installation acceptance. No overlays, generative edits or image retouching. Steam upload remains pending. The selected scouting target is unscouted; question marks are actual game mechanics. Match results are genuine, including the loss.\n\n## Further polish observed\n\nThe squad cards and training layout still use substantial vertical space; the training energy display remains inconsistent with the profile. Those need real UI fixes rather than screenshot retouching. Full 5v5 calibration and release acceptance are separate open tasks.\n`);
  console.log(JSON.stringify({directory,count:screenshots.length,dimensions:'1920x1080',build:manifest.buildId}));
}
main().catch(error=>{console.error(error);process.exitCode=1;});
